import React, { useState } from 'react';
import Background from '../components/Background';
import MeshSphere from '../components/MeshSphere';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

export default function Home({ setPage, streak }) {
  const [text,    setText]    = useState('');
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');
  const [result,  setResult]  = useState(null);
  const { addThought } = useThoughts();

  const handleSubmit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      const entry = { id:Date.now(), user_text:text, ...ai, date:new Date().toISOString() };
      addThought(entry); setResult(entry);
    } catch { setError('Kunde inte analysera just nu. Försök igen.'); }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={()=>{setResult(null);setText('');}} setPage={setPage}/>;

  return (
    <div style={{ minHeight:'100vh', paddingBottom:96, position:'relative', overflow:'hidden' }}>
      <Background mood="default" />

      {/* Spiral wordmark — top left, small */}
      <div style={{ position:'absolute', top:24, left:24, zIndex:10 }}>
        <span style={{ fontSize:13, fontWeight:700, letterSpacing:'-0.02em', color:'rgba(28,25,23,0.45)' }}>Spiral</span>
      </div>

      {/* Streak — top right */}
      {streak > 0 && (
        <div style={{ position:'absolute', top:20, right:24, zIndex:10 }}>
          <span style={{ fontSize:12, color:'rgba(28,25,23,0.4)', fontWeight:400 }}>🔥 {streak}</span>
        </div>
      )}

      {/* Big orb — takes up top half, bleeds slightly */}
      <div style={{ display:'flex', justifyContent:'center', paddingTop:56, position:'relative', zIndex:1, animation:'fadeIn 1s ease both' }}>
        <MeshSphere size={300} speed={0.45} distort={0.4} />
      </div>

      {/* Editorial text block — like Technical Poets, text takes space */}
      <div style={{ padding:'0 24px', position:'relative', zIndex:1, animation:'fadeUp .8s .2s both' }}>

        {/* Large question — mixed weight like Nextly */}
        <h1 style={{ fontSize:'clamp(30px,7.5vw,48px)', lineHeight:1.18, letterSpacing:'-0.035em', color:'#1c1917', marginBottom:20 }}>
          Vad är det som{' '}
          <span style={{ fontStyle:'italic', fontWeight:300, color:'rgba(28,25,23,0.45)' }}>snurrar</span>
          <br/>i huvudet just nu?
        </h1>

        {/* Thin divider */}
        <div style={{ height:1, background:'rgba(28,25,23,0.08)', marginBottom:20 }} />

        {/* Input — minimal, borderless */}
        <div style={{ marginBottom:14 }}>
          <textarea
            value={text}
            onChange={e => setText(e.target.value)}
            maxLength={1000}
            placeholder="Skriv fritt — inga rätta svar..."
            style={{
              width:'100%', minHeight:88,
              background:'rgba(255,255,255,0.55)',
              backdropFilter:'blur(16px)',
              border:'1px solid rgba(255,255,255,0.82)',
              borderRadius:18,
              color:'#1c1917', fontSize:15, fontWeight:300,
              lineHeight:1.78, resize:'none', outline:'none',
              padding:'14px 16px',
              boxShadow:'0 2px 12px rgba(0,0,0,0.04)',
            }}
          />
          {error && <p style={{ fontSize:12, color:'rgba(180,60,60,0.8)', marginTop:6 }}>{error}</p>}
        </div>

        {/* Submit */}
        <button
          onClick={handleSubmit}
          disabled={!text.trim() || loading}
          style={{
            width:'100%', padding:'15px',
            borderRadius:100,
            background: text.trim() && !loading ? '#1c1917' : 'rgba(0,0,0,0.08)',
            color: text.trim() && !loading ? '#f2efea' : 'rgba(28,25,23,0.28)',
            fontSize:14, fontWeight:600, border:'none',
            boxShadow: text.trim() && !loading ? '0 4px 20px rgba(0,0,0,0.16)' : 'none',
            transition:'all .25s', marginBottom:12,
          }}>
          {loading
            ? <span style={{ display:'flex', alignItems:'center', justifyContent:'center', gap:8 }}>
                <span style={{ width:11, height:11, border:'2px solid rgba(242,239,234,0.3)', borderTopColor:'#f2efea', borderRadius:'50%', display:'inline-block', animation:'spin .7s linear infinite' }}/>
                Analyserar...
              </span>
            : 'Analysera →'}
        </button>

        {/* Quick links — horizontal, very minimal */}
        <div style={{ display:'flex', gap:8 }}>
          {[
            { id:'checkin',   label:'Check-in' },
            { id:'breathing', label:'Andning' },
          ].map(({ id, label }) => (
            <button key={id} onClick={() => setPage(id)}
              style={{
                flex:1, padding:'12px',
                background:'rgba(255,255,255,0.5)',
                backdropFilter:'blur(12px)',
                border:'1px solid rgba(255,255,255,0.78)',
                borderRadius:14,
                fontSize:13, fontWeight:500,
                color:'rgba(28,25,23,0.55)',
                transition:'all .2s',
                boxShadow:'0 1px 6px rgba(0,0,0,0.04)',
              }}
              onMouseEnter={e => { e.currentTarget.style.color='#1c1917'; e.currentTarget.style.background='rgba(255,255,255,0.72)'; }}
              onMouseLeave={e => { e.currentTarget.style.color='rgba(28,25,23,0.55)'; e.currentTarget.style.background='rgba(255,255,255,0.5)'; }}>
              {label}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

// ── Analysis result ───────────────────────────────────────────
function Analysis({ result, text, onBack, setPage }) {
  return (
    <div style={{ minHeight:'100vh', paddingBottom:96, position:'relative', overflow:'hidden' }}>
      <Background mood="warm" />

      <div style={{ position:'absolute', top:24, left:24, zIndex:10 }}>
        <span style={{ fontSize:13, fontWeight:700, letterSpacing:'-0.02em', color:'rgba(28,25,23,0.4)' }}>Spiral</span>
      </div>

      {/* Smaller orb */}
      <div style={{ display:'flex', justifyContent:'center', paddingTop:56, marginBottom:0, animation:'fadeIn .8s ease both' }}>
        <MeshSphere size={200} speed={0.3} distort={0.55} />
      </div>

      <div style={{ padding:'0 24px', animation:'fadeUp .7s .1s both' }}>

        {/* Quote */}
        <p style={{ fontSize:12, color:'rgba(28,25,23,0.38)', fontStyle:'italic', lineHeight:1.7, marginBottom:16, paddingLeft:12, borderLeft:'2px solid rgba(28,25,23,0.1)' }}>
          "{text.slice(0, 120)}{text.length > 120 ? '...' : ''}"
        </p>

        {/* Trap label — big */}
        <div style={{ marginBottom:22 }}>
          <p style={{ fontSize:11, fontWeight:600, textTransform:'uppercase', letterSpacing:'0.08em', color:'rgba(28,25,23,0.35)', marginBottom:5 }}>
            {result.trap_icon} Tankefälla
          </p>
          <h2 style={{ fontSize:'clamp(26px,7vw,40px)', fontWeight:700, letterSpacing:'-0.04em', lineHeight:1.05, color:'#1c1917' }}>
            {result.trap_label}
          </h2>
        </div>

        {/* Thin divider */}
        <div style={{ height:1, background:'rgba(28,25,23,0.07)', marginBottom:18 }} />

        {/* Info sections — clean, minimal glass */}
        {[
          { label:'Vad händer',  body: result.description },
          { label:'Omramning',   body: result.reframe },
          { label:'Övning',      body: result.exercise_text },
        ].map(({ label, body }) => (
          <div key={label} style={{ marginBottom:12,
            background:'rgba(255,255,255,0.52)',
            backdropFilter:'blur(16px)',
            border:'1px solid rgba(255,255,255,0.78)',
            borderRadius:18, padding:'14px 16px',
            boxShadow:'0 2px 10px rgba(0,0,0,0.04)',
          }}>
            <p style={{ fontSize:11, fontWeight:600, textTransform:'uppercase', letterSpacing:'0.07em', color:'rgba(28,25,23,0.35)', marginBottom:7 }}>{label}</p>
            <p style={{ fontSize:14, color:'rgba(28,25,23,0.75)', lineHeight:1.82, fontWeight:300 }}>{body}</p>
          </div>
        ))}

        <div style={{ display:'flex', gap:8, marginTop:4 }}>
          <button onClick={() => setPage('breathing')}
            style={{ flex:1, padding:'13px', borderRadius:14, background:'rgba(255,255,255,0.52)', border:'1px solid rgba(255,255,255,0.78)', color:'rgba(28,25,23,0.55)', fontSize:13, backdropFilter:'blur(12px)', transition:'all .2s' }}>
            🫁 Andning
          </button>
          <button onClick={onBack}
            style={{ padding:'13px 18px', fontSize:13, color:'rgba(28,25,23,0.38)', fontWeight:400 }}>
            ← Tillbaka
          </button>
        </div>
      </div>
    </div>
  );
}
